// Parsowanie wiadomosci email plus normalizacja.
const msg = $json;
const from = msg.from?.value?.[0]?.address || msg.from || '';
const subject = msg.subject || '';
const text = (msg.text || msg.textAsHtml || '').toString().trim();

// Wyciagnij numer zamowienia z tematu lub tresci.
const orderIdRegex = /(?:zam[oó]wienie|order|ord|#)[ #]*([0-9]{4,10})/i;
const orderMatch = (subject + ' ' + text).match(orderIdRegex);
const extractedOrderId = orderMatch ? orderMatch[1] : null;

// Wyciagnij custom naglowek jesli wczesniej byla korespondencja.
const customHeader = msg.headers?.['x-wismo-session'];
const sessionId = customHeader || `email_${from.replace(/[^a-z0-9]/gi, '_')}_${Date.now()}`;

// Sanityzacja tresci: usun cytaty odpowiedzi (linie zaczynajace sie od >, sygnatury po --).
let cleanText = text
  .replace(/^>.*$/gm, '')
  .split(/^-- $/m)[0]
  .replace(/\n{3,}/g, '\n\n')
  .trim();

if (!cleanText) {
  return [{ json: { error: 'empty_message', from } }];
}

return [{
  json: {
    session_id: sessionId,
    channel: 'email',
    user_message: cleanText,
    metadata: {
      from,
      subject,
      extracted_order_id: extractedOrderId,
      message_id: msg.messageId,
      in_reply_to: msg.inReplyTo
    },
    ts: new Date().toISOString()
  }
}];

// Format HTML dla emaila plus sygnatura sklepu.
const reply = $json.reply || '(brak odpowiedzi)';
const storeName = $env.STORE_NAME || 'Sklep';
const supportEmail = $env.SUPPORT_EMAIL || 'support@example.com';
const orderId = $node['Parse Email'].json.metadata.extracted_order_id;

// Konwersja podstawowego markdown do HTML.
let htmlBody = reply
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/\n\n/g, '</p><p>')
  .replace(/\n/g, '<br>')
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/\*(.+?)\*/g, '<em>$1</em>');

const html = `<!DOCTYPE html><html><body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; max-width: 600px; margin: 0 auto; color: #12182A; line-height: 1.6;">
<p>${htmlBody}</p>
<hr style="border: none; border-top: 1px solid #D8D3C7; margin: 24px 0;">
<p style="font-size: 12px; color: #5A6478;">${storeName}. Wiadomosc wygenerowana automatycznie. Odpowiedz aby porozmawiac dalej.<br>Kontakt: ${supportEmail}</p>
</body></html>`;

return [{
  json: {
    subject: orderId ? `Re: zamowienie #${orderId}` : `Odpowiedz od ${storeName}`,
    html,
    text: reply,
    custom_headers: {
      'X-WISMO-Session': $node['Parse Email'].json.session_id,
      'X-Auto-Response': 'wismo-agent'
    }
  }
}];
